        .filter(|demand| bare(&demand.specifier))
        .collect();
    demands.extend(data.imports.iter().filter(|binding| bare(&binding.specifier)).map(|binding| Demand {
        from: file.to_owned(),
        specifier: Box::from(binding.specifier.as_str()),
        name: CompactString::default(),
    }));
    demands.sort();
    demands.dedup();
    demands
}

